import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SevenFigureMistakeProps = Record<string, any>;

const SevenFigureMistake: React.FC<SevenFigureMistakeProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  text1 = "7 FIGURE",
  text2 = "MISTAKE",
  text1Color = "#32CD32", // Bright Green
  text2Color = "#FF0000", // Bright Red
  text1Size = 180,
  text2Size = 250,
  shakeIntensity = 20,
}) => {
  useFontLoader(["Anton"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing
  const text1Start = 5;
  const text2Start = 25; // 20 frames later

  // 1. "7 FIGURE" Animation: Spring Scale Up
  const text1Scale = spring({
    frame: frame - text1Start,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  const text1Opacity = interpolate(
    frame,
    [text1Start, text1Start + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 2. "MISTAKE" Animation: Snap In + Punch
  const text2Scale = spring({
    frame: frame - text2Start,
    fps,
    config: {
      damping: 10,
      stiffness: 200, // Higher stiffness for "snap"
      mass: 0.8,
    },
  });

  const text2Opacity = interpolate(
    frame,
    [text2Start, text2Start + 5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Shake Effect on "MISTAKE"
  // Active for 15 frames after appearance
  const shakeDuration = 15;
  const shakeProgress = interpolate(
    frame - text2Start,
    [0, shakeDuration],
    [1, 0], // Decays from 1 to 0
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Random jitter based on frame + seed
  const shakeX = (random(`x-${frame}`) - 0.5) * shakeIntensity * shakeProgress;
  const shakeY = (random(`y-${frame}`) - 0.5) * shakeIntensity * shakeProgress;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Anton",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        transition: "none",
      }}
    >
      {/* Container for proper spacing */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: height * 0.02, // 2% of height gap
        }}
      >
        {/* TEXT 1: 7 FIGURE */}
        <div
          style={{
            fontSize: text1Size, // Use pixel values from slider for simplicity, or convert to relative if strictly needed. Sliders are pixels here.
            color: text1Color,
            lineHeight: 0.9,
            textAlign: "center",
            opacity: text1Opacity,
            transform: `scale(${text1Scale})`,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
          }}
        >
          {text1}
        </div>

        {/* TEXT 2: MISTAKE */}
        <div
          style={{
            fontSize: text2Size,
            color: text2Color,
            lineHeight: 0.9,
            textAlign: "center",
            opacity: text2Opacity,
            // Combine scale spring with shake offsets
            transform: `scale(${text2Scale}) translate(${shakeX}px, ${shakeY}px)`,
            textTransform: "uppercase",
            textShadow: "0px 10px 30px rgba(0,0,0,0.5)", // Add depth
          }}
        >
          {text2}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SevenFigureMistake;